package com.mamtrex.hospital.nursing;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="nursing_observations") public class NursingObservation extends BaseEntity { private String patientId; private String temperatureC; private String bloodPressure; private String heartRate; private String note; protected NursingObservation(){} public NursingObservation(String patientId, String temperatureC, String bloodPressure, String heartRate, String note){this.patientId=patientId; this.temperatureC=temperatureC; this.bloodPressure=bloodPressure; this.heartRate=heartRate; this.note=note;} public String getPatientId(){return patientId;} public String getTemperatureC(){return temperatureC;} public String getBloodPressure(){return bloodPressure;} public String getHeartRate(){return heartRate;} public String getNote(){return note;} }
